package pl.maciek.squashscoreboard;

import android.app.Activity;import android.graphics.Color;import android.os.Bundle;import android.view.*;import android.widget.*;import org.json.JSONObject;
/** Displays one chosen history chart at full screen size. */
public class ChartFullscreenActivity extends Activity {
 public static final String EXTRA_RECORD="record",EXTRA_CHART="chart";
 @Override public void onCreate(Bundle state){super.onCreate(state);try{showChart(MatchRecord.fromJson(new JSONObject(getIntent().getStringExtra(EXTRA_RECORD))),getIntent().getIntExtra(EXTRA_CHART,0));}catch(Exception e){finish();}}
 private void showChart(MatchRecord r,int chart){boolean dark=AppPreferences.dark(this);int bg=dark?Color.rgb(13,16,22):Color.rgb(245,247,250),fg=dark?Color.WHITE:Color.rgb(24,30,40),muted=dark?Color.rgb(174,185,201):Color.rgb(80,92,108);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(10),dp(18),dp(10));root.setBackgroundColor(bg);TextView back=text("<  WROC",17,muted);back.setGravity(Gravity.CENTER_VERTICAL);back.setOnClickListener(v->finish());String title=chart==0?"PUNKTY W CZASIE":chart==1?"PRZEBIEG SETOW":"WYNIKI SETOW";TextView caption=text(title+"  -  "+r.playerOneName+" vs "+r.playerTwoName,21,fg);caption.setGravity(Gravity.CENTER);root.addView(back,new LinearLayout.LayoutParams(-1,dp(35)));root.addView(caption,new LinearLayout.LayoutParams(-1,dp(42)));View view=chart==0?new ScoreChartView(this,r):chart==1?new SetProgressChartView(this,r):new SetsChartView(this,r);if(view instanceof ScoreChartView)((ScoreChartView)view).setInteractive(true);if(view instanceof SetProgressChartView)((SetProgressChartView)view).setInteractive(true);root.addView(view,new LinearLayout.LayoutParams(-1,0,1));if(chart==1){SetProgressChartView setView=(SetProgressChartView)view;Button allSets=new Button(this);allSets.setText("POKAŻ WSZYSTKIE SETY");allSets.setAllCaps(false);allSets.setTextColor(Color.WHITE);allSets.setBackgroundColor(AppPreferences.GREEN);allSets.setVisibility(View.GONE);allSets.setOnClickListener(v->setView.showAllSets());setView.setOnSetFocusChanged(number->{caption.setText(number==0?"PRZEBIEG SETÓW · DOTKNIJ SETU":"SET "+number+" · "+r.playerOneName+" vs "+r.playerTwoName);allSets.setVisibility(number==0?View.GONE:View.VISIBLE);});caption.setText("PRZEBIEG SETÓW · DOTKNIJ SETU");root.addView(allSets,new LinearLayout.LayoutParams(-1,dp(38)));}LinearLayout legend=new LinearLayout(this);legend.setGravity(Gravity.CENTER);TextView p1=text("● "+r.playerOneName,16,r.playerOneColor),p2=text("● "+r.playerTwoName,16,r.playerTwoColor);legend.addView(p1,new LinearLayout.LayoutParams(0,-1,1));legend.addView(p2,new LinearLayout.LayoutParams(0,-1,1));root.addView(legend,new LinearLayout.LayoutParams(-1,dp(32)));setContentView(root);}private TextView text(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);return v;}private int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}
}
